/**
 * AuthFlow synthetic data seed.
 *
 * Idempotent: clears existing rows, then inserts with a fixed faker seed so the
 * data set is identical on every run. Every date is computed relative to the
 * moment the seed runs, so charts always show a live 90 day curve. Required
 * documents are generated by the real rules engine so the checklist on each
 * request stays consistent with the payer criteria.
 *
 * Synthetic data only. No real patient information.
 */

import { PrismaClient } from "@prisma/client"
import { faker } from "@faker-js/faker"
import { buildRequiredDocuments } from "../lib/rules"
import type {
  Diagnosis,
  LabResult,
  PatientChart,
  PriorTherapy,
  RuleCriteria,
} from "../types"

const prisma = new PrismaClient()

faker.seed(20260627)

const now = new Date()
const H = 3_600_000
const DAY = 24 * H
const minus = (ms: number) => new Date(now.getTime() - ms)
const plus = (ms: number) => new Date(now.getTime() + ms)
const addMs = (date: Date, ms: number) => new Date(date.getTime() + ms)
const ri = (min: number, max: number) => faker.number.int({ min, max })
const pick = <T>(arr: T[]): T => faker.helpers.arrayElement(arr)
const isoDate = (date: Date) => date.toISOString().slice(0, 10)
const titleCase = (s: string) =>
  s.replace(/\w\S*/g, (t) => t.charAt(0).toUpperCase() + t.slice(1).toLowerCase())

