function qualifyingDx(code: string): Diagnosis {
  return DX_SPECIFIC[code] ?? { code, label: "Documented condition" }
}

function failedTrial(req: string): PriorTherapy {
  const r = req.toLowerCase()
  if (r.includes("metformin"))
    return { name: "Metformin", drugClass: "Biguanide", outcome: "failed", note: "A1c remained above goal after 6 months" }
  if (r.includes("methotrexate") || r.includes("dmard"))
    return { name: "Methotrexate", drugClass: "Conventional DMARD", outcome: "failed", note: "Inadequate response after a 3 month trial" }
  if (r.includes("topical"))
    return { name: "Topical corticosteroids", drugClass: "Topical steroid", outcome: "failed", note: "Disease persisted despite adherence" }
  if (r.includes("tnf"))
    return { name: "Adalimumab", drugClass: "TNF inhibitor", outcome: "intolerant", note: "Discontinued for injection-site reactions" }
  if (r.includes("phototherapy") || r.includes("uvb"))
    return { name: "Narrowband UVB phototherapy", drugClass: "Phototherapy", outcome: "failed", note: "No durable response after 24 sessions" }
  return { name: titleCase(req), drugClass: "Prior therapy", outcome: "failed", note: "Documented trial and failure" }
}

function labResult(label: string): LabResult {
  const l = label.toLowerCase()
  const date = isoDate(minus(DAY * ri(6, 110)))
  if (l.includes("tb"))
    return { name: "QuantiFERON-TB Gold", value: "Negative", date, flag: "normal" }
  if (l.includes("hepatitis"))
    return { name: "Hepatitis B surface antigen", value: "Non-reactive", date, flag: "normal" }
  if (l.includes("hba1c") || l.includes("a1c"))
    return { name: "HbA1c", value: (ri(76, 108) / 10).toFixed(1), unit: "%", date, flag: "high" }
  if (l.includes("egfr"))
    return { name: "eGFR", value: String(ri(55, 96)), unit: "mL/min/1.73m2", date, flag: "normal" }
  if (l.includes("cbc"))
    return { name: "CBC with differential", value: "Within normal limits", date, flag: "normal" }
  if (l.includes("pd-l1"))
    return { name: "PD-L1 IHC 22C3", value: `TPS ${ri(20, 90)}%`, date, flag: "normal" }
  if (l.includes("eosin"))
    return { name: "Eosinophil count", value: String(ri(320, 720)), unit: "cells/uL", date, flag: "high" }
  return { name: label, value: "Documented", date, flag: "normal" }
}

type ChartProfile = "complete" | "missingStep" | "missingDx" | "missingLabs" | "minimal"

function makeChart(crit: RuleCriteria, profile: ChartProfile): PatientChart {
  const diagnoses: Diagnosis[] = []
  const priorTherapies: PriorTherapy[] = []
  const labs: LabResult[] = []

  // Qualifying diagnosis
  if (crit.requiredDiagnoses.length > 0) {
    diagnoses.push(
      profile === "missingDx"
        ? pick(UNRELATED_DX)
        : qualifyingDx(crit.requiredDiagnoses[0]),
    )
  }
  if (profile !== "minimal" && faker.datatype.boolean(0.6)) {
    diagnoses.push(pick(COMORBIDITIES))
  }

  // Step therapy
  if (crit.stepTherapyRequired || crit.requiredPriorTherapies.length > 0) {
    if (profile === "complete" || profile === "missingLabs" || profile === "missingDx") {
      priorTherapies.push(failedTrial(crit.requiredPriorTherapies[0] ?? "preferred agent"))
    } else if (profile === "missingStep") {
      priorTherapies.push({ name: "Ibuprofen", drugClass: "NSAID", outcome: "ongoing", note: "Current symptomatic therapy" })
    }
  }

  // Labs
  if (profile !== "missingLabs" && profile !== "minimal") {
    for (const lab of crit.requiredLabs) labs.push(labResult(lab))
  }
  if (profile === "complete" || profile === "missingStep") {
    labs.push(labResult("CBC with differential"))
  }

  return { diagnoses, priorTherapies, labs }
}

