function justificationText(
  patientFirst: string,
  dx: string,
  drug: string,
  trial: PriorTherapy | undefined,
  plan: string,
): string {
  const trialPhrase = trial
    ? `an inadequate response to ${trial.name}`
    : `disease not controlled on first-line therapy`
  return `${patientFirst} has ${dx} with ${trialPhrase}. ${drug} is medically necessary to achieve disease control and is requested per ${plan} criteria.`
}

function letterText(args: {
  patientName: string
  dx: string
  drug: string
  trial?: PriorTherapy
  plan: string
  provider: string
  specialty: string
}): string {
  const { patientName, dx, drug, trial, plan, provider, specialty } = args
  const trialLine = trial
    ? `The patient previously completed a trial of ${trial.name}, which was ${trial.outcome}. `
    : `First-line management has not produced adequate disease control. `
  return [
    `To the Utilization Management Department at ${plan}:`,
    "",
    `I am writing to document the medical necessity of ${drug} for my patient, ${patientName}, who carries a diagnosis of ${dx}. ${trialLine}Continued disease activity warrants escalation of therapy.`,
    "",
    `In my clinical judgment as a ${specialty} specialist, ${drug} is the most appropriate next step and is consistent with accepted guidelines and the plan's published criteria. I respectfully request approval of this prior authorization.`,
    "",
    `Sincerely,`,
    `${provider}, ${specialty}`,
    "",
    `This letter is a draft prepared for clinician review. It is generated from synthetic data and must be reviewed and signed before submission.`,
  ].join("\n")
}

