// ---------------------------------------------------------------------------
// Status timeline
// ---------------------------------------------------------------------------

type EventSeed = { fromStatus: string | null; toStatus: string; note: string; createdAt: Date }

function buildTimeline(
  status: string,
  plan: string,
  times: {
    createdAt: Date
    submittedAt?: Date | null
    decisionAt?: Date | null
  },
  extra: { denialReason?: string; appealStatus?: string },
): EventSeed[] {
  const { createdAt, submittedAt, decisionAt } = times
  const events: EventSeed[] = []
  const docAt = addMs(createdAt, H * 2)

  if (status === "Draft") {
    return [{ fromStatus: null, toStatus: "Draft", note: "Request created from a point-of-care order.", createdAt }]
  }

  events.push({
    fromStatus: null,
    toStatus: "NeedsDocumentation",
    note: "Order captured at point of care; required documentation identified.",
    createdAt,
  })

  if (status === "NeedsDocumentation") {
    events.push({
      fromStatus: "NeedsDocumentation",
      toStatus: "NeedsDocumentation",
      note: "Chart auto-fill completed. Some required items still need to be captured.",
      createdAt: docAt,
    })
    return events
  }

  const readyAt = submittedAt ? addMs(submittedAt, -H * 3) : addMs(createdAt, H * 4)
  events.push({
    fromStatus: "NeedsDocumentation",
    toStatus: "ReadyToSubmit",
    note: "All required documentation satisfied from the chart.",
    createdAt: readyAt,
  })

  if (status === "ReadyToSubmit") return events

  if (submittedAt) {
    events.push({
      fromStatus: "ReadyToSubmit",
      toStatus: "Submitted",
      note: `Submitted to ${plan}.`,
      createdAt: submittedAt,
    })
  }

  if (status === "Submitted") return events

  const reviewAt = submittedAt ? addMs(submittedAt, H * ri(2, 10)) : addMs(createdAt, H * 8)
  events.push({
    fromStatus: "Submitted",
    toStatus: "InReview",
    note: `${plan} acknowledged the request; under adjudication.`,
    createdAt: reviewAt,
  })

  if (status === "InReview") return events

  if (status === "Approved" && decisionAt) {
    events.push({
      fromStatus: "InReview",
      toStatus: "Approved",
      note: `Approved by ${plan}.`,
      createdAt: decisionAt,
    })
  }

  if ((status === "Denied" || status === "Appealed") && decisionAt) {
    events.push({
      fromStatus: "InReview",
      toStatus: "Denied",
      note: `Denied: ${extra.denialReason ?? "criteria not met"}`,
      createdAt: decisionAt,
    })
  }

  if (status === "Appealed" && decisionAt) {
    events.push({
      fromStatus: "Denied",
      toStatus: "Appealed",
      note: `Appeal ${extra.appealStatus ?? "submitted"}.`,
      createdAt: addMs(decisionAt, H * ri(6, 36)),
    })
  }

  return events
}

// ---------------------------------------------------------------------------
// Build plan of requests
// ---------------------------------------------------------------------------

type Flow = "approved" | "denied" | "appealed" | "inreview" | "submitted" | "ready" | "open" | "draft"

type OrderSpec = {
  status: string
  profile: ChartProfile
  flow: Flow
  risk?: "atRisk" | "overdue"
}

function buildOrderSpecs(): OrderSpec[] {
  const specs: OrderSpec[] = []
  const push = (n: number, s: OrderSpec) => {
    for (let i = 0; i < n; i++) specs.push({ ...s })
  }

  push(16, { status: "Approved", profile: "complete", flow: "approved" })
  push(9, { status: "InReview", profile: "complete", flow: "inreview" })
  push(6, { status: "Submitted", profile: "complete", flow: "submitted" })
  push(5, { status: "ReadyToSubmit", profile: "complete", flow: "ready" })
  push(6, { status: "Denied", profile: "complete", flow: "denied" })
  push(3, { status: "Appealed", profile: "complete", flow: "appealed" })
  push(3, { status: "Draft", profile: "minimal", flow: "draft" })

  const needsProfiles: ChartProfile[] = [
    "missingStep", "missingLabs", "missingDx", "missingStep",
    "missingLabs", "missingStep", "missingDx", "missingLabs", "missingStep",
  ]
  needsProfiles.forEach((profile) => specs.push({ status: "NeedsDocumentation", profile, flow: "open" }))

  // Inject deadline pressure for the risk widgets.
  const markFirst = (status: string, flow: Flow, risk: "atRisk" | "overdue", count: number) => {
    let marked = 0
    for (const s of specs) {
      if (marked >= count) break
      if (s.status === status && s.flow === flow && !s.risk) {
        s.risk = risk
        marked++
      }
    }
  }
  markFirst("NeedsDocumentation", "open", "overdue", 2)
  markFirst("NeedsDocumentation", "open", "atRisk", 2)
  markFirst("ReadyToSubmit", "ready", "atRisk", 1)
  markFirst("InReview", "inreview", "atRisk", 2)
  markFirst("Submitted", "submitted", "atRisk", 1)

  return faker.helpers.shuffle(specs)
}

function timesFor(flow: Flow, risk?: "atRisk" | "overdue") {
  let createdAt: Date
  let submittedAt: Date | null = null
  let decisionAt: Date | null = null
  let deadline: Date

  const normalDeadline = () => plus(DAY * ri(3, 9))
  const riskDeadline = () =>
    risk === "overdue" ? minus(H * ri(2, 22)) : risk === "atRisk" ? plus(H * ri(15, 45)) : normalDeadline()

  switch (flow) {
    case "approved":
    case "denied":
    case "appealed": {
      createdAt = minus(DAY * ri(12, 82))
      submittedAt = addMs(createdAt, H * ri(6, 48))
      const reviewAt = addMs(submittedAt, H * ri(3, 14))
      decisionAt = addMs(reviewAt, H * ri(8, 110))
      if (decisionAt.getTime() > now.getTime() - H * 2) decisionAt = minus(H * ri(3, 96))
      if (decisionAt.getTime() < submittedAt.getTime()) decisionAt = addMs(submittedAt, H * ri(10, 60))
      deadline = addMs(submittedAt, DAY * ri(3, 7))
      break
    }
    case "inreview": {
      createdAt = minus(DAY * ri(1, 14))
      submittedAt = addMs(createdAt, H * ri(4, 40))
      if (submittedAt.getTime() >= now.getTime()) {
        submittedAt = new Date((createdAt.getTime() + now.getTime()) / 2)
      }
      deadline = riskDeadline()
      break
    }
    case "submitted": {
      createdAt = minus(DAY * ri(0, 6) + H * ri(1, 20))
      submittedAt = addMs(createdAt, H * ri(2, 18))
      if (submittedAt.getTime() >= now.getTime()) {
        submittedAt = new Date((createdAt.getTime() + now.getTime()) / 2)
      }
      deadline = riskDeadline()
      break
    }
    case "ready": {
      createdAt = minus(DAY * ri(0, 6) + H * ri(1, 20))
      deadline = riskDeadline()
      break
    }
    case "open": {
      createdAt = minus(DAY * ri(0, 12) + H * ri(1, 20))
      deadline = riskDeadline()
      break
    }
    case "draft": {
      createdAt = minus(H * ri(1, 30))
      deadline = plus(DAY * ri(4, 10))
      break
    }
  }

  const turnaroundHours =
    submittedAt && decisionAt
      ? Math.round(((decisionAt.getTime() - submittedAt.getTime()) / H) * 10) / 10
      : null

  return { createdAt, submittedAt, decisionAt, deadline, turnaroundHours }
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main() {
  console.log("Clearing existing data...")
  await prisma.generationLog.deleteMany()
  await prisma.statusEvent.deleteMany()
  await prisma.requiredDocument.deleteMany()
  await prisma.priorAuthRequest.deleteMany()
  await prisma.payerRule.deleteMany()
  await prisma.patient.deleteMany()
  await prisma.medication.deleteMany()
  await prisma.provider.deleteMany()
  await prisma.payer.deleteMany()

  console.log("Seeding payers, providers, medications...")
  const payers = await Promise.all(
    PAYERS.map((p) => prisma.payer.create({ data: p })),
  )

  const providers = await Promise.all(
    SPECIALTIES.map((specialty) =>
      prisma.provider.create({
        data: {
          firstName: faker.person.firstName(),
          lastName: faker.person.lastName(),
          npi: faker.string.numeric(10),
          specialty,
        },
      }),
    ),
  )
  const providerBySpecialty = new Map(providers.map((p) => [p.specialty, p]))

  const allMeds = [...SPECIALTY_MEDS, ...GENERIC_MEDS]
  const medRecords = await Promise.all(
    allMeds.map((m) =>
      prisma.medication.create({
        data: {
          name: m.name,
          brandName: m.brandName,
          drugClass: m.drugClass,
          ndc: m.ndc,
          hcpcs: m.hcpcs ?? null,
          cpt: m.cpt ?? null,
          isSpecialty: m.isSpecialty,
          route: m.route,
          indication: m.indication,
        },
      }),
    ),
  )
  const medByName = new Map(medRecords.map((r) => [r.name, r]))
  const seedByName = new Map(allMeds.map((m) => [m.name, m]))

  console.log("Seeding payer rules...")
  for (const payer of payers) {
    for (const med of allMeds) {
      const rec = medByName.get(med.name)!
      await prisma.payerRule.create({
        data: {
          payerId: payer.id,
          medicationId: rec.id,
          paRequired: med.criteria.paRequired,
          stepTherapyRequired: med.criteria.stepTherapyRequired,
          requiredDiagnoses: JSON.stringify(med.criteria.requiredDiagnoses),
          requiredPriorTherapies: JSON.stringify(med.criteria.requiredPriorTherapies),
          requiredLabs: JSON.stringify(med.criteria.requiredLabs),
          quantityLimit: med.criteria.quantityLimit,
          criteriaSummary: med.criteria.criteriaSummary,
        },
      })
    }
  }

  console.log("Seeding prior authorization requests...")
  const specs = buildOrderSpecs()
  let refSeq = 2500

  for (const spec of specs) {
    const med = pick(SPECIALTY_MEDS)
    const medRec = medByName.get(med.name)!
    const payer = pick(payers)
    const provider =
      providerBySpecialty.get(MED_SPECIALTY[med.name] ?? "Internal Medicine") ??
      pick(providers)
    const crit = med.criteria
    const chart = makeChart(crit, spec.profile)

    const firstName = faker.person.firstName()
    const lastName = faker.person.lastName()
    const patientName = `${firstName} ${lastName}`
    const memberId = `${faker.string.alpha({ length: 3, casing: "upper" })}${faker.string.numeric(9)}`
    const providerName = `Dr. ${provider.firstName} ${provider.lastName}`

    const t = timesFor(spec.flow, spec.risk)
    const hasLetter =
      spec.flow === "approved" ||
      spec.flow === "denied" ||
      spec.flow === "appealed" ||
      spec.flow === "inreview" ||
      spec.flow === "submitted" ||
      spec.flow === "ready"

    const docs = buildRequiredDocuments({
      drugName: med.name,
      criteria: crit,
      chart,
      memberId,
      providerName,
      providerNpi: provider.npi,
      hasLetterOfMedicalNecessity: hasLetter,
    })

    const primaryDx = chart.diagnoses[0] ?? { code: "R69", label: "Illness, unspecified" }
    const trial = chart.priorTherapies.find((p) =>
      ["failed", "intolerant", "partial"].includes(p.outcome),
    )

    const denialReason =
      spec.flow === "denied" || spec.flow === "appealed" ? pick(DENIAL_REASONS) : null
    const appealStatus = spec.flow === "appealed" ? pick(APPEAL_STATES) : null

    const isWorked = spec.flow !== "draft"
    const clinicalJustification = isWorked
      ? justificationText(firstName, primaryDx.label, med.name, trial, payer.name)
      : null
    const letterOfMedicalNecessity = hasLetter
      ? letterText({
          patientName,
          dx: primaryDx.label,
          drug: med.name,
          trial,
          plan: payer.name,
          provider: providerName,
          specialty: provider.specialty,
        })
      : null

    const events = buildTimeline(spec.status, payer.name, t, {
      denialReason: denialReason ?? undefined,
      appealStatus: appealStatus ?? undefined,
    })

    // Urgent and STAT skew toward deadline-pressured requests.
    const priority = spec.risk
      ? faker.helpers.weightedArrayElement([
          { weight: 5, value: "Urgent" },
          { weight: 3, value: "STAT" },
          { weight: 2, value: "Routine" },
        ])
      : faker.helpers.weightedArrayElement([
          { weight: 6, value: "Routine" },
          { weight: 3, value: "Urgent" },
          { weight: 1, value: "STAT" },
        ])

    refSeq += 1

    await prisma.priorAuthRequest.create({
      data: {
        referenceId: `PA-${refSeq}`,
        status: spec.status,
        priority,
        diagnosisCode: primaryDx.code,
        diagnosisLabel: primaryDx.label,
        clinicalJustification,
        letterOfMedicalNecessity,
        denialReason,
        appealStatus,
        assignedCoordinator: isWorked ? pick(COORDINATORS) : null,
        createdAt: t.createdAt,
        submittedAt: t.submittedAt,
        decisionAt: t.decisionAt,
        deadline: t.deadline,
        turnaroundHours: t.turnaroundHours,
        patient: {
          create: {
            firstName,
            lastName,
            dateOfBirth: faker.date.birthdate({ mode: "age", min: 19, max: 86 }),
            sex: pick(["Female", "Male"]),
            mrn: `MRN-${faker.string.numeric(7)}`,
            memberId,
            diagnoses: JSON.stringify(chart.diagnoses),
            priorTherapies: JSON.stringify(chart.priorTherapies),
            labs: JSON.stringify(chart.labs),
            weightKg: ri(52, 122),
            payer: { connect: { id: payer.id } },
          },
        },
        provider: { connect: { id: provider.id } },
        medication: { connect: { id: medRec.id } },
        payer: { connect: { id: payer.id } },
        requiredDocuments: {
          create: docs.map((d) => ({
            label: d.label,
            source: d.source,
            satisfied: d.satisfied,
            evidence: d.evidence ?? null,
          })),
        },
        statusEvents: {
          create: events.map((e) => ({
            fromStatus: e.fromStatus,
            toStatus: e.toStatus,
            note: e.note,
            createdAt: e.createdAt,
          })),
        },
      },
    })
  }

  console.log("Seeding AI generation telemetry...")
  const genLogs = []
  for (let i = 0; i < 64; i++) {
    const status = faker.helpers.weightedArrayElement([
      { weight: 24, value: "ok" },
      { weight: 1, value: "rate_limited" },
      { weight: 1, value: "error" },
      { weight: 1, value: "capped" },
    ])
    const realModel = status === "ok" && faker.datatype.boolean(0.65)
    genLogs.push({
      model: realModel ? "claude-opus-4-8" : "template",
      usedFallback: !realModel,
      status,
      latencyMs: realModel ? ri(1200, 4200) : ri(4, 40),
      inputTokens: realModel ? ri(360, 520) : null,
      outputTokens: realModel ? ri(280, 520) : null,
      createdAt: minus(DAY * ri(0, 14) + H * ri(0, 23)),
    })
  }
  await prisma.generationLog.createMany({ data: genLogs })

  const counts = await prisma.priorAuthRequest.groupBy({
    by: ["status"],
    _count: true,
  })
  console.log("Seed complete. Requests by status:")
  for (const c of counts) console.log(`  ${c.status}: ${c._count}`)
  console.log(`  Total: ${specs.length}`)
}

main()
  .catch((e) => {
    console.error(e)
    process.exit(1)
  })
  .finally(async () => {
    await prisma.$disconnect()
  })
